from sqlalchemy import Column, ForeignKey, Integer, String, cast, func, select
from sqlalchemy.dialects.mysql import BINARY
from sqlalchemy.orm import DeclarativeBase, relationship
class Base(DeclarativeBase): pass
class Account(Base):
    __tablename__ = 'accounts'
    id = Column(Integer, primary_key=True)
    name = Column(String, nullable=False)
    entries = relationship('Entry', order_by='Entry.id')
class Entry(Base):
    __tablename__ = 'entries'
    id = Column(Integer, primary_key=True)
    account_id = Column(ForeignKey('accounts.id'), nullable=False)
    title = Column(String, nullable=False)

def list_accounts(session, term, limit, offset=0):
    for value in (limit, offset):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('limit and offset must be nonnegative integers')
    if limit == 0:
        return []

    accounts = select(Account.id, Account.name)
    if term:
        dialect = session.get_bind(mapper=Account).dialect.name
        title = Entry.title
        if dialect in ('mysql', 'mariadb'):
            title = cast(title, BINARY)
        elif dialect == 'mssql':
            title = title.collate('Latin1_General_100_BIN2')
        matches = title.contains(term, autoescape=True)
        if dialect == 'sqlite':
            # SQLite LIKE ignores ASCII case, even with a binary collation.
            matches = matches & (func.instr(Entry.title, term) > 0)
        accounts = accounts.where(
            select(Entry.id).where(
                Entry.account_id == Account.id,
                matches,
            ).exists()
        )

    page = accounts.order_by(Account.id).offset(offset).limit(limit).subquery()
    statement = (
        select(page.c.id, page.c.name, Entry.id, Entry.title)
        .select_from(page.outerjoin(Entry, Entry.account_id == page.c.id))
        .order_by(page.c.id, Entry.id)
    )
    result = []
    for account_id, name, entry_id, title in session.execute(statement):
        if not result or result[-1]['id'] != account_id:
            result.append({'id': account_id, 'name': name, 'entries': []})
        if entry_id is not None:
            result[-1]['entries'].append({'id': entry_id, 'title': title})
    return result
